package com.bank.query.filter;

import org.springframework.data.domain.Sort;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import java.util.*;

// The ONLY fields a client may sort/filter by. Maps the public API name to a
// safe entity property. Anything else is rejected — no raw column names.
public final class FieldWhitelist {

    private static final Map<String, String> SORTABLE = Map.of(
            "createdAt", "createdAt",
            "amount", "amount",
            "status", "status");

    public static final Set<String> FILTERABLE = Set.of("status", "type", "minAmount", "maxAmount");

    private FieldWhitelist() { }

    // Builds a Sort only from whitelisted fields; rejects anything unknown.
    public static Sort toSort(List<String> sortParams) {
        if (sortParams == null || sortParams.isEmpty()) {
            return Sort.by(Sort.Direction.DESC, "createdAt");
        }
        List<Sort.Order> orders = new ArrayList<>();
        for (String token : sortParams) {
            String[] parts = token.split(",");
            String property = SORTABLE.get(parts[0]);
            if (property == null) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                        "Unsortable field: " + parts[0]);
            }
            Sort.Direction dir = parts.length > 1 && "asc".equalsIgnoreCase(parts[1])
                    ? Sort.Direction.ASC : Sort.Direction.DESC;
            orders.add(new Sort.Order(dir, property));
        }
        if (orders.size() > 3) {   // cap sort keys to prevent pathological queries
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Too many sort keys");
        }
        return Sort.by(orders);
    }
}
