package com.bank.query.service;

import com.bank.query.filter.*;
import com.bank.query.model.Transaction;
import com.bank.query.repository.TransactionRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.data.domain.*;
import org.springframework.data.jpa.domain.Specification;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.List;

@Service
public class TransactionQueryService {

    private static final Logger log = LoggerFactory.getLogger(TransactionQueryService.class);
    private final TransactionRepository repo;

    public TransactionQueryService(TransactionRepository repo) { this.repo = repo; }

    public Page<Transaction> query(String accountId, String status, String type,
                                   BigDecimal minAmount, List<String> sort,
                                   int page, int size) {
        // Sort validated against the whitelist — malicious fields rejected.
        Sort safeSort = FieldWhitelist.toSort(sort);

        // Filters composed from type-safe specifications, no raw strings.
        Specification<Transaction> spec = Specification
                .where(TransactionSpecifications.accountId(accountId))
                .and(TransactionSpecifications.status(status))
                .and(TransactionSpecifications.type(type))
                .and(TransactionSpecifications.minAmount(minAmount));

        log.info("Query account={} status={} type={} minAmount={} sort={}",
                accountId, status, type, minAmount, sort);
        return repo.findAll(spec, PageRequest.of(page, Math.min(size, 100), safeSort));
    }
}
