package com.bank.query.controller;

import com.bank.query.model.Transaction;
import com.bank.query.service.TransactionQueryService;
import org.springframework.data.domain.Page;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;
import java.util.List;

@RestController
@RequestMapping("/api/v1/accounts/{accountId}/transactions")
public class TransactionQueryController {

    private final TransactionQueryService service;

    public TransactionQueryController(TransactionQueryService service) {
        this.service = service;
    }

    // GET ...?status=COMPLETED&type=CREDIT&minAmount=1000&sort=createdAt,desc
    @GetMapping
    public Page<Transaction> list(@PathVariable String accountId,
                                  @RequestParam(required = false) String status,
                                  @RequestParam(required = false) String type,
                                  @RequestParam(required = false) BigDecimal minAmount,
                                  @RequestParam(required = false) List<String> sort,
                                  @RequestParam(defaultValue = "0") int page,
                                  @RequestParam(defaultValue = "20") int size) {
        return service.query(accountId, status, type, minAmount, sort, page, size);
    }
}
